      "@Woher|kommst*|du",
      "@Wie|heißt*|du",
      "@Wo|wohnst*|du",
      "The W-words worth knowing now: **wer** (who), **was** (what), **wo** (where), **woher** (where from), **wohin** (where to), **wann** (when), **wie** (how), **warum** (why).",
      "## Yes/no questions",
