      "## The verb decides",
      "> You cannot work out the case from the meaning. **The verb dictates it**, and you learn it with the verb — exactly like the article with the noun.",
      "## Most verbs take the Akkusativ",
      "= Ich sehe den Film. | \n= Ich kaufe den Tisch. | \n= Ich lese das Buch. |",
      "> That is the normal case, so you only have to remember the **exceptions**.",
      "## The Dativ verbs — learn this short list",
      "= helfen | Ich helfe dem Mann.\n= danken | Ich danke der Frau.\n= gehören | Das Buch gehört dem Kind.\n= gefallen | Der Film gefällt mir.\n= antworten | Ich antworte dem Lehrer.\n= folgen | Ich folge dem Auto.\n= glauben | Ich glaube dir.\n= passen | Die Hose passt mir.",
      "! There are only about a dozen of these, and you meet them constantly. Learning the list once is far cheaper than guessing forever.",
      "## Two objects at once",
      "> Verbs like geben, schenken, zeigen and schicken take **both**: the person in the **Dativ**, the thing in the **Akkusativ**.",
      "= Ich gebe dem Mann das Buch. | person first, thing second\n= Ich zeige der Frau die Stadt. |",
      "! The order flips as soon as you use pronouns: Ich gebe **es ihm** — thing first, person second. Rule of thumb: **short before long, pronoun before noun.**",
      "## gefallen turns the sentence around",
