      "| klein | kleiner | am kleinsten |\n| schnell | schneller | am schnellsten |\n| interessant | interessanter | am interessantesten |",
      "! Note the difference to English: German has **no more/most**. It is *interessanter*, never mehr interessant.",
      "## Short words take an Umlaut",
      "= alt → älter → am ältesten | \n= groß → größer → am größten | \n= jung → jünger → am jüngsten | \n= lang → länger → am längsten |",
      "## The four irregulars worth memorising",
