      "## A noun plus a fixed verb",
      "> German loves to replace a plain verb with a **noun + a fixed verb** — often in formal or written language. The noun carries the meaning; the verb is almost empty and just makes it work.",
      "= eine Entscheidung treffen | to decide (literally: to make a decision)\n= Kritik üben | to criticise\n= zur Verfügung stellen | to provide",
