      "## The verbs that do most of this work",
      "= nehmen | Rücksicht nehmen · in Kauf nehmen · Abschied nehmen · in Anspruch nehmen\n= stellen | zur Verfügung stellen · in Frage stellen · eine Frage stellen\n= treffen | eine Entscheidung treffen · eine Wahl treffen\n= ziehen | in Betracht ziehen · in Erwägung ziehen\n= üben | Kritik üben\n= bringen | zum Ausdruck bringen · zur Sprache bringen\n= leisten | Hilfe leisten · einen Beitrag leisten\n= spielen | eine Rolle spielen",
      "## The one exception",
      "! There is one common combination where **machen** really is correct: **einen Fehler machen**. Otherwise, when in doubt, it is almost certainly not machen.",
      "## Some carry a preposition too",
      "= Kritik üben an | + Dativ — Kritik an dem Plan\n= Rücksicht nehmen auf | + Akkusativ — Rücksicht auf die Kinder\n= Wert legen auf | + Akkusativ — Wert auf Pünktlichkeit\n= Stellung nehmen zu | + Dativ — Stellung zu der Frage",
