      "= Was für ein Auto ist das? | Nominativ → ein\n= Was für einen Wagen suchst du? | Akkusativ → einen\n= In was für einer Stadt wohnst du? | Dativ after in → einer",
      "! Plural or uncountable: drop the ein — **Was für** Bücher liest du? / **Was für** Musik hörst du?",
